mapper.update:
UPDATE MOCK_BANK_ACCOUNT
SET BALANCE_AMT = #{newBalanceAmt},
    UPDATED_AT  = SYSDATE
WHERE BANK_NAME = #{bankName}
  AND ACCOUNT_NO = #{accountNo}

mapper.select:
SELECT NAME
FROM MEMBER
WHERE MEMBER_ID = #{memberId}

SELECT PAYMENT_PROOF_ID
FROM PAYMENT_PROOF
WHERE GROUP_ID  = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND PAY_MONTH = #{payMonth}
  AND ROUND_NO  = #{roundNo}

mapper.update:
UPDATE PAYMENT_PROOF
SET AMOUNT      = #{amount},
    PAY_DATE    = SYSDATE,
    STATUS      = 'PENDING',
    REVIEW_MEMO = #{reviewMemo}
WHERE PAYMENT_PROOF_ID = #{paymentProofId}

mapper.select:
SELECT pp.PAYMENT_PROOF_ID AS paymentProofId, tx.TRAN_ID AS tranId, tx.BANK_TRAN_ID AS bankTranId, pp.GROUP_ID AS groupId, pp.MEMBER_ID AS memberId, m.NAME AS memberName, pp.PAY_MONTH AS payMonth, pp.ROUND_NO AS roundNo, pp.AMOUNT AS amount, pp.STATUS AS status, CASE pp.STATUS WHEN 'PENDING' THEN '확인중' WHEN 'CONFIRMED' THEN '납입완료' WHEN 'REVISION' THEN '보완요청' ELSE pp.STATUS END AS statusKor, NVL(tx.PRINT_CONTENT, m.NAME || '_' || pp.PAY_MONTH || '_' || pp.ROUND_NO || '회차') AS printContent, TO_CHAR(pp.PAY_DATE, 'YYYY-MM-DD HH24:MI:SS') AS payDate, pp.REF_NO AS refNo FROM PAYMENT_PROOF pp JOIN MEMBER m ON pp.MEMBER_ID = m.MEMBER_ID LEFT JOIN MOCK_BANK_TRANSACTION tx ON tx.PAYMENT_PROOF_ID = pp.PAYMENT_PROOF_ID AND tx.INOUT_TYPE = 'DEPOSIT' WHERE pp.GROUP_ID = #{groupId}
AND pp.PAY_MONTH = #{payMonth}
ORDER BY pp.PAY_DATE DESC, pp.PAYMENT_PROOF_ID DESC
